function g3BrokenLineQuestion(d){
 const count=d===0?ri(2,3):d===1?ri(3,4):ri(4,5),lengths=[],pts=[{x:2,y:6}];let x=2,y=6;
 for(let i=0;i<count;i++){
  let len;
  if(i%2===0){len=ri(1,Math.min(3,11-x));x+=len}
  else{const goUp=(i%4===1),room=goUp?y-1:7-y;len=ri(1,Math.max(1,Math.min(3,room)));y+=goUp?-len:len}
  lengths.push(len);pts.push({x,y})
 }
 const answer=lengths.reduce((a,b)=>a+b,0),measures=lengths.map((v,i)=>({a:i,b:i+1,text:`${v} см`,offset:i%2?18:-18})),data={kind:"broken",points:pts,measures,aria:"Ломаная с подписанными длинами звеньев"};
 return g3GeoNumber("Найдите длину ломаной.",answer,`Складываем длины всех звеньев:<br>${lengths.join(" + ")} = <b>${answer} см</b>.`,`g3:broken_line_length:${d}:${lengths.join("-")}`,{type:"g3BrokenLength",lengths,answer,points:pts,journalText:`Звенья: ${lengths.join(", ")} см.`},data,"см")
}
function g3PerimeterQuestion(d){
 const units=["см","дм","м"],unit=g6RandomFrom(units),variant=d===0?g6RandomFrom(["rectangle","triangle"]):d===1?g6RandomFrom(["rectangle","square","triangle"]):g6RandomFrom(["rectangle","square","polygon"]);let pts,sides,answer,text,ex;
 if(variant==="rectangle"){
  const a=ri(2,7),b=ri(2,5);pts=[{x:3,y:2},{x:3+a,y:2},{x:3+a,y:2+b},{x:3,y:2+b}];sides=[a,b,a,b];answer=2*(a+b);text=`Найдите периметр прямоугольника со сторонами <b>${a} ${unit}</b> и <b>${b} ${unit}</b>.`;ex=`Периметр — сумма всех сторон:<br>${a} + ${b} + ${a} + ${b} = <b>${answer} ${unit}</b>.`
