 }else if(variant==="triangle"){
  const k=ri(1,2);pts=[{x:3,y:6},{x:3,y:6-3*k},{x:3+4*k,y:6}];sides=[3*k,5*k,4*k];answer=12*k;text="Найдите периметр треугольника по подписанным сторонам.";ex=`Складываем все стороны: ${sides.join(" + ")} = <b>${answer} ${unit}</b>.`
 }else{
  pts=[{x:3,y:2},{x:8,y:2},{x:8,y:5},{x:6,y:5},{x:6,y:7},{x:3,y:7}];sides=[5,3,2,2,3,5];answer=20;text="Найдите периметр многоугольника по подписанным сторонам.";ex=`Складываем длины всех сторон: ${sides.join(" + ")} = <b>${answer} ${unit}</b>.`
 }
 const measures=sides.map((v,i)=>({a:i,b:(i+1)%pts.length,text:`${v} ${unit}`,offset:i%2?18:-18})),data={kind:"polygon",points:pts,measures,aria:"Многоугольник с подписанными длинами сторон"};
 return g3GeoNumber(text,answer,ex,`g3:perimeter:${d}:${variant}:${sides.join("-")}:${unit}`,{type:"g3Perimeter",variant,sides,answer,unit,points:pts,journalText:`Стороны: ${sides.join(", ")} ${unit}.`},data,unit)
}
