 }else if(d===1){
   const variant=Math.random()<.5?"wordToFraction":"fractionToWord";
   if(variant==="wordToFraction")q=g3ChoiceQuestion(`Какая запись означает «<b>${name}</b>»?`,String(n),[{key:String(n),label:g3UnitFractionHtml(n)},...other.map(x=>({key:String(x),label:g3UnitFractionHtml(x)}))],`${name[0].toUpperCase()+name.slice(1)} записывается как ${g3UnitFractionHtml(n)}.`,`g3:parts_intro:${d}:${variant}:${n}`,{variant,denom:n},true);
   else q=g3ChoiceQuestion(`Как называется доля ${g3UnitFractionHtml(n)}?`,String(n),[{key:String(n),label:name},...other.map(x=>({key:String(x),label:g3UnitFractionName(x)}))],`${g3UnitFractionHtml(n)} — это <b>${name}</b>.`,`g3:parts_intro:${d}:${variant}:${n}`,{variant,denom:n},true);
 }else{
   const variant=Math.random()<.5?"visualFraction":"visualName";
   if(variant==="visualFraction")q=g3ChoiceQuestion(`Какая доля выделена на рисунке?`,String(n),[{key:String(n),label:g3UnitFractionHtml(n)},...other.map(x=>({key:String(x),label:g3UnitFractionHtml(x)}))],`Целое разделено на ${g3EqualPartsPhrase(n)} и выделена одна: ${g3UnitFractionHtml(n)}.`,`g3:parts_intro:${d}:${variant}:${n}`,{variant,denom:n},true);
   else q=g3ChoiceQuestion(`Как называется выделенная на рисунке доля?`,String(n),[{key:String(n),label:name},...other.map(x=>({key:String(x),label:g3UnitFractionName(x)}))],`Выделена одна из ${n} равных частей — <b>${name}</b>.`,`g3:parts_intro:${d}:${variant}:${n}`,{variant,denom:n},true);
